SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for nb_advertisement
-- ----------------------------
DROP TABLE IF EXISTS `nb_advertisement`;
CREATE TABLE `nb_advertisement`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '广告ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '广告标题',
  `image` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '广告图片',
  `position` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '展示位置（banner/sidebar/popup/footer）',
  `link_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '链接地址',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `sort` int NULL DEFAULT 0 COMMENT '排序',
  `status` int NULL DEFAULT 0 COMMENT '状态（0待审核 1已发布）',
  `click_count` int NULL DEFAULT 0 COMMENT '点击量',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_position`(`position` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_sort`(`sort` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '广告表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of nb_advertisement
-- ----------------------------
INSERT INTO `nb_advertisement` VALUES ('2', '助农政策宣传', 'data:image/png;base64,', 'sidebar', 'https://example.com/policy', '2025-01-15 00:00:00', '2025-06-30 23:59:59', 2, 1, 850, NULL, '2025-10-24 11:06:07', NULL, NULL, NULL);
INSERT INTO `nb_advertisement` VALUES ('3', '农贸市场招商', 'data:image/png;base64,', 'popup', 'https://example.com/market', '2025-02-01 00:00:00', '2025-03-31 23:59:59', 3, 0, 0, NULL, '2025-10-24 11:06:07', NULL, NULL, NULL);

-- ----------------------------
-- Table structure for nb_allowance_policy
-- ----------------------------
DROP TABLE IF EXISTS `nb_allowance_policy`;
CREATE TABLE `nb_allowance_policy`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '政策ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '标题',
  `author` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '作者',
  `resume` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '摘要',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '内容',
  `image` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '封面图批量图',
  `browse_num` int NULL DEFAULT 0 COMMENT '浏览量',
  `publish_status` int NULL DEFAULT 0 COMMENT '发布状态（0未发布/草稿 1已发布/上架）',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `recommend` int NULL DEFAULT 0 COMMENT '推荐（0普通 1推荐）',
  `created_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '录入发表时间',
  `updated_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '录存修改时间',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '惠农政策表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of nb_allowance_policy
-- ----------------------------
INSERT INTO `nb_allowance_policy` VALUES ('038c0e7bb97db2962b4087599e84828b', '农业保险补贴政策', '财政部、农业农村部', '农户购买农业保险可享受保费补贴', '为降低农业生产风险，对农户购买种植业、养殖业保险，中央和地方财政给予保费50%-80%的补贴支持。包括水稻、小麦、玉米、大豆等主要粮食作物保险和生猪、奶牛等畜牧业保险。', 'https://i.pravatar.cc/150?img=16', 180, 1, '2025-10-24 10:09:53', 1, NULL, NULL, NULL, NULL, NULL, '2025-10-24 10:15:31', '农业技术');
INSERT INTO `nb_allowance_policy` VALUES ('04fdfdc7abbbda8b960e4a4a4bf72608', '2025年粮食种植补贴政策', '农业农村部', '对种植水稻、小麦、玉米等粮食作物的农户给予每亩补贴', '为保障国家粮食安全，鼓励农民种粮积极性，对种植水稻、小麦、玉米等粮食作物的农户，按照实际种植面积给予每亩200元的直接补贴。补贴资金由中央财政和地方财政共同承担，确保及时足额发放到农户手中。', 'https://i.pravatar.cc/150?img=16', 150, 0, '2025-10-24 01:57:41', 1, NULL, NULL, NULL, NULL, NULL, '2025-10-24 10:15:31', NULL);
INSERT INTO `nb_allowance_policy` VALUES ('092cd30011a2cb9b0f1d57f58837b3f7', '农机购置补贴实施方案', '农业农村部', '购买农业机械设备可享受30%-50%的补贴', '为推动农业机械化发展，对购买拖拉机、收割机、播种机、植保无人机等农业机械的农户和农业合作社，给予购置价格30%-50%的财政补贴。单户年度补贴总额不超过30万元。', 'https://i.pravatar.cc/150?img=16', 200, 1, '2025-10-22 21:03:13', 1, NULL, NULL, NULL, NULL, NULL, '2025-10-24 10:15:31', NULL);
INSERT INTO `nb_allowance_policy` VALUES ('2b1d267975cd4f1fae34d7f60f574dea', '农业保险补贴政策', '财政部、农业农村部', '农户购买农业保险可享受保费补贴', '为降低农业生产风险，对农户购买种植业、养殖业保险，中央和地方财政给予保费50%-80%的补贴支持。包括水稻、小麦、玉米、大豆等主要粮食作物保险和生猪、奶牛等畜牧业保险。', 'https://i.pravatar.cc/150?img=16', 180, 1, '2025-10-24 01:57:41', 1, NULL, NULL, NULL, NULL, NULL, '2025-10-24 10:15:31', NULL);
INSERT INTO `nb_allowance_policy` VALUES ('360d0aa27d4a3497d321a57d7b28dae1', '乡村振兴产业发展补贴', '国家乡村振兴局', '发展特色农业产业可申请专项资金支持', '支持乡村特色产业发展，对发展特色种植、养殖、加工、乡村旅游等产业项目，可申请10-50万元的专项资金支持。重点支持一村一品、农产品加工、电商物流等项目。', 'https://i.pravatar.cc/150?img=16', 95, 0, NULL, 0, NULL, NULL, NULL, NULL, NULL, '2025-10-24 10:15:31', NULL);
INSERT INTO `nb_allowance_policy` VALUES ('38c1c7c0253654d0fbb16f7685139b4b', '乡村振兴产业发展补贴', '国家乡村振兴局', '发展特色农业产业可申请专项资金支持', '支持乡村特色产业发展，对发展特色种植、养殖、加工、乡村旅游等产业项目，可申请10-50万元的专项资金支持。重点支持一村一品、农产品加工、电商物流等项目。', 'https://i.pravatar.cc/150?img=16', 95, 1, '2025-10-24 02:19:04', 0, NULL, NULL, NULL, NULL, NULL, '2025-10-24 10:15:31', NULL);
INSERT INTO `nb_allowance_policy` VALUES ('6e76dc16e922d7e50a887b7566a4f7c9', '2025年粮食种植补贴政策', '农业农村部', '对种植水稻、小麦、玉米等粮食作物的农户给予每亩补贴', '为保障国家粮食安全，鼓励农民种粮积极性，对种植水稻、小麦、玉米等粮食作物的农户，按照实际种植面积给予每亩200元的直接补贴。补贴资金由中央财政和地方财政共同承担，确保及时足额发放到农户手中。', 'https://i.pravatar.cc/150?img=16', 150, 1, '2025-10-22 21:03:13', 1, NULL, NULL, NULL, NULL, NULL, '2025-10-24 10:15:31', NULL);
INSERT INTO `nb_allowance_policy` VALUES ('76925ff0d97aca23c0c2ee76702f7300', '设施农业建设补助政策', '农业农村部', '建设温室大棚、智能养殖场等可获得补助', '支持发展现代设施农业，对新建或改造温室大棚、智能养殖场、冷链仓储设施等项目，按照投资额度给予20%-40%的财政补助。单个项目补助金额最高不超过100万元。', 'https://i.pravatar.cc/150?img=16', 120, 1, '2025-10-22 21:03:13', 0, NULL, NULL, NULL, NULL, NULL, '2025-10-24 10:15:31', NULL);
INSERT INTO `nb_allowance_policy` VALUES ('7d1e8df6f8e8ca5af23bec2ccef1f3b8', '农机购置补贴实施方案', '农业农村部', '购买农业机械设备可享受30%-50%的补贴', '为推动农业机械化发展，对购买拖拉机、收割机、播种机、植保无人机等农业机械的农户和农业合作社，给予购置价格30%-50%的财政补贴。单户年度补贴总额不超过30万元。', 'https://i.pravatar.cc/150?img=16', 200, 1, '2025-10-24 10:09:53', 1, NULL, NULL, NULL, NULL, NULL, '2025-10-24 10:15:31', NULL);
