-- ----------------------------
-- Table structure for nb_credit_loan
-- ----------------------------
DROP TABLE IF EXISTS `nb_credit_loan`;
CREATE TABLE `nb_credit_loan`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '贷款ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '标题',
  `author` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '作者',
  `resume` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '摘要',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '内容',
  `image` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '封面图批量图',
  `browse_num` int NULL DEFAULT 0 COMMENT '浏览量',
  `publish_status` int NULL DEFAULT 0 COMMENT '发布状态（0未发布/草稿 1已发布/上架）',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `recommend` int NULL DEFAULT 0 COMMENT '推荐（0普通 1推荐）',
  `created_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '录入发表时间',
  `updated_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '录存修改时间',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '信用贷款表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of nb_credit_loan
-- ----------------------------
INSERT INTO `nb_credit_loan` VALUES ('095301cccb8fed96305c66af7f5b398f', '农业产业链金融服务', '邮储银行', '全产业链金融支持方案', '针对农业产业链上下游企业，提供种植、加工、流通、销售全链条的金融服务。单户最高1000万元授信额度，灵活的还款方式，支持订单融资、应收账款融资等多种模式。', '/images/loan3.jpg', 180, 1, '2025-10-24 10:09:53', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `nb_credit_loan` VALUES ('0c802a7d361329bf55d3c12e4a1c7003', '乡村创业担保贷款', '人社部、财政部', '返乡创业可享受贴息贷款', '支持返乡农民工、大学生、退役军人等人员在农村创业，提供最高50万元的创业担保贷款，财政给予全额贴息，降低创业成本。用于农产品加工、电商、乡村旅游等创业项目。', '/images/loan4.jpg', 220, 0, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `nb_credit_loan` VALUES ('15d9aaa9d2020ccefe653787620dc167', '新型农业经营主体贷款', '农业银行', '家庭农场、合作社专属贷款产品', '面向家庭农场、农民合作社、农业企业等新型农业经营主体，提供最高500万元的信贷支持，利率优惠，用于扩大生产规模、购置设备、土地流转等。支持线上申请，手续简便。', '/images/loan2.jpg', 250, 1, '2025-10-22 21:03:13', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `nb_credit_loan` VALUES ('542cf12d0bab526317eaf5a7cc7b07bc', '农业产业链金融服务', '邮储银行', '全产业链金融支持方案', '针对农业产业链上下游企业，提供种植、加工、流通、销售全链条的金融服务。单户最高1000万元授信额度，灵活的还款方式，支持订单融资、应收账款融资等多种模式。', '/images/loan3.jpg', 180, 1, '2025-10-22 21:03:13', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `nb_credit_loan` VALUES ('785869657fafab4bda083ca8e72b7235', '农户小额信用贷款', '农业银行', '无需抵押，最高可贷30万元', '专为农户设计的小额信用贷款产品，凭借良好信用记录即可申请，无需抵押担保，贷款额度最高30万元，年化利率4.5%-5.5%，用于农业生产经营、购买农资、农机等。申请便捷，当天审批，快速放款。', '/images/loan1.jpg', 300, 1, '2025-10-22 21:03:13', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `nb_credit_loan` VALUES ('8783c9c6285925a48a36548aaa0e1903', '农业产业链金融服务', '邮储银行', '全产业链金融支持方案', '针对农业产业链上下游企业，提供种植、加工、流通、销售全链条的金融服务。单户最高1000万元授信额度，灵活的还款方式，支持订单融资、应收账款融资等多种模式。', '/images/loan3.jpg', 180, 1, '2025-10-24 01:57:41', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `nb_credit_loan` VALUES ('be29d808602f83d67482f340bd764a92', '乡村创业担保贷款', '人社部、财政部', '返乡创业可享受贴息贷款', '支持返乡农民工、大学生、退役军人等人员在农村创业，提供最高50万元的创业担保贷款，财政给予全额贴息，降低创业成本。用于农产品加工、电商、乡村旅游等创业项目。', '/images/loan4.jpg', 220, 0, '2025-10-24 02:19:15', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `nb_credit_loan` VALUES ('c0c1815ae52144827bcb0be6bd6440b8', '新型农业经营主体贷款', '农业银行', '家庭农场、合作社专属贷款产品', '面向家庭农场、农民合作社、农业企业等新型农业经营主体，提供最高500万元的信贷支持，利率优惠，用于扩大生产规模、购置设备、土地流转等。支持线上申请，手续简便。', '/images/loan2.jpg', 250, 1, '2025-10-24 01:57:41', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

-- ----------------------------
-- Table structure for nb_expert
-- ----------------------------
DROP TABLE IF EXISTS `nb_expert`;
CREATE TABLE `nb_expert`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '专家ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '专家姓名',
  `avatar` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '专家头像',
  `specialty` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '专业领域',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '职称',
  `organization` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '所属机构',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '联系电话',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '电子邮箱',
  `introduction` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '个人简介',
  `service_count` int NULL DEFAULT 0 COMMENT '服务次数',
  `rating` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '评分',
  `status` int NULL DEFAULT 1 COMMENT '状态（0不可用 1可用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_specialty`(`specialty` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '农业专家表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of nb_expert
-- ----------------------------
INSERT INTO `nb_expert` VALUES ('1', '张教授', 'data:image/png;base64,', '水稻种植技术', '教授/博士生导师', '中国农业大学', '138-0000-0001', 'zhang@example.com', '从事水稻种植研究30年,主持国家级科研项目10余项,发表SCI论文50余篇。', 156, '4.9', 1, NULL, '2025-10-24 11:06:07', NULL, NULL, '农业技术');
INSERT INTO `nb_expert` VALUES ('2', '李专家', 'data:image/png;base64,', '蔬菜病虫害防治', '研究员', '农业科学院', '138-0000-0002', 'li@example.com', '蔬菜病虫害防治专家,擅长绿色防控技术,服务农户超过1000家。', 203, '4.8', 1, NULL, '2025-10-24 11:06:07', NULL, NULL, NULL);
INSERT INTO `nb_expert` VALUES ('3', '王老师', 'data:image/png;base64,', '果树栽培管理', '高级农艺师', '农业技术推广中心', '138-0000-0003', 'wang@example.com', '果树栽培专家,指导建立现代化果园50余个,培训果农3000余人次。', 178, '4.7', 1, NULL, '2025-10-24 11:06:07', NULL, NULL, NULL);

-- ----------------------------
-- Table structure for nb_farm_market
-- ----------------------------
DROP TABLE IF EXISTS `nb_farm_market`;
CREATE TABLE `nb_farm_market`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '市场ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '市场名称',
  `region_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '区域ID',
  `created_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '录入发表时间',
  `updated_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '录存修改时间',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '农产品市场表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of nb_farm_market
-- ----------------------------
INSERT INTO `nb_farm_market` VALUES (1, '绿色农贸批发市场', '城市-朝阳区', NULL, NULL, NULL, '2019-01-15 09:30:00', NULL, NULL, '北京市朝阳区大型综合性农贸批发市场，成立于2019年，主营蔬菜、水果、粮油等农产品批发业务。市场占地面积8000平方米，设有100个固定摊位，配备现代化冷链仓储设施。');
INSERT INTO `nb_farm_market` VALUES (2, '鲜果集市', '城市-海淀区', NULL, NULL, NULL, '2020-02-20 14:20:00', NULL, NULL, '海淀区知名专业水果批发市场，创建于2020年2月，是北京市重点农产品批发市场之一。市场专注于提供国内外优质水果，建有5000平米标准化冷库，配备全程冷链物流配送系统。');
INSERT INTO `nb_farm_market` VALUES (3, '田园综合市场', '郊区-顺义区', NULL, NULL, NULL, '2018-03-10 08:00:00', NULL, NULL, '顺义区现代化农产品综合交易市场，2018年3月建成投入使用。集农产品交易、仓储、初加工、配送于一体，是北京市农业产业化重点龙头企业。市场总占地面积20000平方米。');
INSERT INTO `nb_farm_market` VALUES (4, '有机蔬菜交易中心', '郊区-大兴区', NULL, NULL, NULL, '2021-04-05 10:15:00', NULL, NULL, '大兴区首家专业有机蔬菜交易中心，成立于2021年4月，专注于绿色有机蔬菜的批发与配送。市场与周边30余家有机蔬菜种植基地签订直采协议，所有产品均通过国家有机产品认证。');
INSERT INTO `nb_farm_market` VALUES (5, '畜禽产品批发市场', '城市-丰台区', NULL, NULL, NULL, '2017-06-12 07:45:00', NULL, NULL, '丰台区大型畜禽产品专业批发市场，始建于2017年6月，是北京市肉类产品主要集散地之一。市场经营猪肉、牛肉、羊肉、禽蛋等畜禽产品，建有标准化冷藏库3000平方米。');
INSERT INTO `nb_farm_market` VALUES (6, '水产海鲜大市场', '城市-石景山区', NULL, NULL, NULL, '2019-09-25 06:30:00', NULL, NULL, '石景山区规模最大的水产品批发交易市场，创立于2019年9月，是北京西部地区水产品集散中心。市场经营淡水鱼、海水鱼、虾蟹贝类等200余种水产品，配备大型海鲜暂养池和冷链设施。');
INSERT INTO `nb_farm_market` VALUES (7, '粮油调味品批发中心', '郊区-通州区', NULL, NULL, NULL, '2020-08-18 09:00:00', NULL, NULL, '通州区专业粮油调味品批发市场，2020年8月正式运营，是北京东部地区粮油副食品重要集散地。市场经营大米、面粉、食用油、调味品等千余种商品，年交易额超3亿元。');
INSERT INTO `nb_farm_market` VALUES (8, '农副产品综合市场', '城市-东城区', NULL, NULL, NULL, '2015-05-20 08:30:00', NULL, NULL, '东城区历史悠久的综合性农贸市场，始创于2015年5月，是北京市二级农产品批发市场。市场经营蔬菜、水果、肉类、水产、粮油等全品类农副产品，服务周边10万居民。');
INSERT INTO `nb_farm_market` VALUES (9, '特色农产品展销中心', '郊区-昌平区', NULL, NULL, NULL, '2022-03-15 10:00:00', NULL, NULL, '昌平区特色农产品展销交易平台，建立于2022年3月，主营昌平及周边地区特色农产品，包括草莓、苹果、大枣、板栗等地方特产，集展销、体验、电商于一体。');
INSERT INTO `nb_farm_market` VALUES (10, '社区便民菜市场', '城市-西城区', NULL, NULL, NULL, '2021-10-08 08:30:00', NULL, NULL, '西城区标准化社区便民菜市场，2021年10月改造升级完成，是北京市\"菜篮子\"工程示范市场。市场环境整洁、管理规范，经营蔬菜、水果、肉蛋等日常生活必需品，服务周边5000余户居民。');

-- ----------------------------
-- Table structure for nb_farm_produce
-- ----------------------------
DROP TABLE IF EXISTS `nb_farm_produce`;
CREATE TABLE `nb_farm_produce`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '产品ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '标题',
  `resume` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '摘要',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '描述',
  `image` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '封面图批量图',
  `catgory` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '类别',
  `produce_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '农产品类型',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '价格',
  `browse_num` int NULL DEFAULT 0 COMMENT '浏览量',
  `push_status` int NULL DEFAULT 0 COMMENT '推荐上报线下展核对线下 1最高获高薪获',
  `push_time` datetime NULL DEFAULT NULL COMMENT '推送时间',
  `recommend` int NULL DEFAULT 0 COMMENT '推荐（0普通 1推荐）',
  `provider_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `account_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '账号ID',
  `created_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '录入发表时间',
  `updated_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '录存修改时间',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '农产品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of nb_farm_produce
-- ----------------------------
INSERT INTO `nb_farm_produce` VALUES ('33a7e5ec46c36f4e99e75da18c8280ad', '新鲜蔬菜礼盒', '当季时令蔬菜组合', '精选当季新鲜蔬菜，包含西红柿、黄瓜、青菜、茄子等10种蔬菜，农场直供，当天采摘当天配送，新鲜美味，绿色健康。', 'data:image/png;base64,', '蔬菜', '绿色', 38.00, 450, 1, '2025-10-24 10:09:53', 1, '阳光蔬菜基地', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `nb_farm_produce` VALUES ('4327bc4a9a435bc8e3e92a0d1fc43b52', '烟台红富士苹果', '山东烟台特产苹果', '山东烟台特产红富士苹果，果大色艳，脆甜多汁，富含维生素C和膳食纤维。精选果径80mm以上优质果，5斤礼盒装。', 'data:image/png;base64,', '水果', '绿色', 29.90, 380, 1, '2025-10-24 01:57:41', 0, '烟台果园', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `nb_farm_produce` VALUES ('4afed8fd6d8ea6f66402ef72eb69b076', '明前龙井茶', '杭州西湖龙井茶', '杭州西湖龙井明前茶，清明前采摘的嫩芽，香气浓郁，回味甘甜，茶汤清澈明亮。传统手工炒制，保留天然茶香。250克精装礼盒。', 'data:image/png;base64,', '茶叶', '有机', 168.00, 280, 0, NULL, 0, '西湖茶庄', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `nb_farm_produce` VALUES ('4f967e6b04499baaba73ad0f0f83fc15', '新鲜蔬菜礼盒', '当季时令蔬菜组合', '精选当季新鲜蔬菜，包含西红柿、黄瓜、青菜、茄子等10种蔬菜，农场直供，当天采摘当天配送，新鲜美味，绿色健康。', 'data:image/png;base64,', '蔬菜', '绿色', 38.00, 450, 1, '2025-10-22 21:03:13', 1, '阳光蔬菜基地', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `nb_farm_produce` VALUES ('795289bc1c3ac00bcb1a78737d2f9007', '烟台红富士苹果', '山东烟台特产苹果', '山东烟台特产红富士苹果，果大色艳，脆甜多汁，富含维生素C和膳食纤维。精选果径80mm以上优质果，5斤礼盒装。', 'data:image/png;base64,', '水果', '绿色', 29.90, 380, 1, '2025-10-24 10:09:53', 0, '烟台果园', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `nb_farm_produce` VALUES ('ba96722920733fb80f31fe77c8a0dc01', '散养土鸡蛋', '农家散养土鸡蛋', '山区散养土鸡所产，鸡只自由觅食，食用天然谷物和虫草，蛋黄金黄饱满，营养价值高，富含卵磷脂。30枚精品装。', 'data:image/png;base64,', '禽蛋', '散养', 45.00, 600, 1, '2025-10-22 21:03:13', 1, '山里人家养殖场', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

-- ----------------------------
-- Table structure for nb_graphic_course
-- ----------------------------
DROP TABLE IF EXISTS `nb_graphic_course`;
CREATE TABLE `nb_graphic_course`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '课程ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '课程标题',
  `teacher` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '讲师',
  `resume` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '课程摘要',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '课程内容',
  `image` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '课程封面图',
  `category` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '课程分类',
  `browse_num` int NULL DEFAULT 0 COMMENT '浏览次数',
  `publish_status` int NULL DEFAULT 0 COMMENT '发布状态（0未发布/草稿 1已发布/上架）',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `recommend` int NULL DEFAULT 0 COMMENT '推荐（0普通 1推荐）',
  `created_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '录入发表时间',
  `updated_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '录存修改时间',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '图文课程表' ROW_FORMAT = Dynamic;

-- ----------------------------
