INSERT INTO `nb_graphic_course` VALUES ('066708f0f6ead91fde8cbe3be681635b', '水稻种植技术指南', '李教授', '详细介绍水稻从育秧到收获的全过程种植技术', '本课程系统讲解水稻种植的关键技术要点，包括品种选择、育秧管理、田间管理、病虫害防治等内容。', '/images/course/rice.jpg', '种植技术', 156, 1, '2025-10-24 10:09:53', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `nb_graphic_course` VALUES ('27280db5022ad4ea765714175158fb11', '有机蔬菜栽培技术', '王老师', '从零开始学习有机蔬菜种植的实用技术', '课程涵盖有机蔬菜的土壤准备、种子处理、田间管理、病虫害生物防治等核心内容。', '/images/course/vegetables.jpg', '种植技术', 203, 1, '2025-10-24 10:09:53', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `nb_graphic_course` VALUES ('2c3c38bd3bebd48cbe97635b2b95b630', '农业病虫害识别与防治', '陈老师', '学会识别常见农业病虫害，掌握科学防治方法', '课程包含水稻、小麦、玉米等作物的主要病虫害识别特征及综合防治策略。', '/images/course/pest-control.jpg', '病虫害防治', 245, 1, '2025-10-24 10:09:53', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
