-- ----------------------------
-- Table structure for nb_service
-- ----------------------------
DROP TABLE IF EXISTS `nb_service`;
CREATE TABLE `nb_service`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '服务ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '服务标题',
  `image` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '服务图片',
  `resume` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '服务摘要',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '服务内容',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '服务类别',
  `provider` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '服务商名称',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '联系电话',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '服务价格',
  `status` int NULL DEFAULT 1 COMMENT '状态(0下架 1上架)',
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '服务地址',
  `order_count` int NULL DEFAULT 0 COMMENT '订单数量',
  `rating` decimal(3, 1) NULL DEFAULT NULL COMMENT '评分',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_category`(`category` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '农业服务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of nb_service
-- ----------------------------
INSERT INTO `nb_service` VALUES ('1', '有机肥料配送服务', 'data:image/png;base64,', '提供优质有机肥料,全程冷链配送,确保肥料新鲜度', '我们提供最优质的有机肥料,来源可追溯,质量有保障。专业团队提供施肥指导,确保农作物健康成长。', 'supply', '绿色农资公司', '400-888-8888', 120.00, 1, '浙江省杭州市余杭区', 358, 4.8, NULL, '2025-10-24 11:06:07', NULL, NULL, NULL);
INSERT INTO `nb_service` VALUES ('2', '农机租赁与维修服务', 'data:image/png;base64,', '提供各类农机租赁服务,包括拖拉机、收割机、播种机等', '专业农机租赁服务,设备齐全,价格优惠。提供上门维修保养服务,确保农机正常运转。', 'machinery', '农机服务中心', '400-777-7777', 200.00, 1, '山东省济南市历城区', 245, 4.5, NULL, '2025-10-24 11:06:07', NULL, NULL, NULL);
INSERT INTO `nb_service` VALUES ('3', '病虫害防治指导', 'https://via.placeholder.com/400x240/e6a23c/fff?text=技术指导', '专业农技师提供病虫害识别与防治方案', '资深农技师团队,提供上门诊断服务,制定科学防治方案,确保农作物健康生长。', 'tech', '农技服务站', '400-666-6666', 150.00, 1, '江苏省南京市江宁区', 189, 4.7, NULL, '2025-10-24 11:06:07', NULL, NULL, NULL);

-- ----------------------------
-- Table structure for nb_video_course
-- ----------------------------
DROP TABLE IF EXISTS `nb_video_course`;
CREATE TABLE `nb_video_course`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '课程ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '课程标题',
  `teacher` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '讲师',
  `resume` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '课程摘要',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '课程内容',
  `image` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '课程封面图',
  `video_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '视频地址',
  `duration` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '视频时长',
  `category` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '课程分类',
  `browse_num` int NULL DEFAULT 0 COMMENT '浏览次数',
  `publish_status` int NULL DEFAULT 0 COMMENT '发布状态（0未发布/草稿 1已发布/上架）',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `recommend` int NULL DEFAULT 0 COMMENT '推荐（0普通 1推荐）',
  `created_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '录入发表时间',
  `updated_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '录存修改时间',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '视频课程表' ROW_FORMAT = Dynamic;

