INSERT INTO `nb_video_course` VALUES ('26f803d1af841ab451f1ac95f56c7b31', '小麦高产栽培技术', '赵教授', '视频讲解小麦高产栽培的关键技术措施', '本视频课程从品种选择、播种技术、肥水管理、病虫害防治等方面全面介绍小麦高产栽培技术。', '/images/course/wheat.jpg', '/videos/wheat-cultivation.mp4', '45分钟', '种植技术', 312, 1, '2025-10-24 02:55:55', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
